import {ATTRIBUTES,SKILLS,SUITS,CHEMS,uid,newCharacter,radPenalty,effectiveStrain,suitFor,suitActive,attribute,skillPool,hullDamage,fireWeapon,reloadWeapon,quote,buy,sell,useChem,validateCharacter} from './rules.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={person:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 21v-3c0-3 3-5 8-5s8 2 8 5v3',armor:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 10h8m-4-4v10',pack:'M5 7h14v14H5z M9 7V3h6v4M5 12h14m-9 0v3h4v-3',medical:'M8 3h8v5h5v8h-5v5H8v-5H3V8h5Z',book:'M5 3h14v18H5z M9 7h6m-6 5h6m-6 5h4',shop:'M3 10h18L19 3H5ZM5 10v11h14V10M9 21v-7h6v7',weapon:'M3 8h17v5H9l-2 7H3l2-9M14 13v3h3v-3',tool:'M14 3a6 6 0 0 0-7 8L2 17l5 5 6-6a6 6 0 0 0 8-7l-4 4-5-5z',food:'M5 3v6c0 3 6 3 6 0V3M8 3v19M18 3v19m0-19c-4 1-4 10 0 10',vehicle:'M3 11l2-6h14l2 6v7H3z M3 11h18M6 15h2m8 0h2M5 18v3m14-3v3',warn:'m12 3 10 18H2z M12 9v6m0 2v1'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.pack}"/></svg>`;
const NAV=[['character','person','Character'],['equipment','weapon','Loadout'],['power','armor','Power armour'],['health','medical','Health'],['inventory','pack','Inventory'],['journal','book','Journal']];
const KEY='fallout-stories-v1';let characters=[],currentId,catalogue=[],tab=location.hash.slice(1)||'character',catalogueSearch='',catalogueCategory='All',cataloguePage=0,inventoryMode='On you',inventoryCategory='',inventoryLocation='',toastTimer,saveProblem=false;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){if(saved.version!==1||!Array.isArray(saved.characters)||!saved.characters.length)throw Error();characters=saved.characters.map(validateCharacter);currentId=saved.currentId;}}catch{saveProblem=true;}
if(!characters.length){characters=[newCharacter()];currentId=characters[0].id;}
let c=characters.find(x=>x.id===currentId)||characters[0];
function persist(){try{if(saveProblem)throw Error('Recovery required');localStorage.setItem(KEY,JSON.stringify({version:1,currentId:c.id,characters}));$('#save-status').textContent='Saved on this device';}catch{$('#save-status').textContent='Not saved · export a backup';}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function commit(message){persist();render();if(message)notify(message);}
function title(kicker,name,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${esc(name)}</h1></div><div class="inline-actions">${actions}</div></div>`;}
function button(label,action,extra='',cls=''){return `<button data-action="${action}" ${extra} class="${cls}">${label}</button>`;}
function field(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label class="full">${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function select(label,name,options,value){return `<label>${esc(label)}<select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function check(label,name,value){return `<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${esc(label)}</label>`;}
function modal(titleText,html){$('#dialog-label').textContent=titleText;$('#dialog-content').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();}
function form(titleText,html,onSubmit){modal(titleText,`<h2>${esc(titleText)}</h2><form id="edit-form"><div class="form-grid">${html}</div><p class="form-error" role="alert" id="form-error"></p><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save changes</button></div></form>`);$('#edit-form').addEventListener('submit',e=>{e.preventDefault();const backup=structuredClone(characters),previousId=c.id;try{const data=new FormData(e.target);onSubmit(data);validateCharacter(c);$('#detail').close();commit();}catch(err){characters=backup;c=characters.find(x=>x.id===previousId)||characters[0];$('#form-error').textContent=err.message;}});}
const num=(d,k)=>Number(d.get(k));
function gauge(label,value,max,path,warning=false){return `<div class="vital ${warning?'warn':''}"><div class="vital-top">${label}<span class="small">${warning?'!':''}</span></div><div class="vital-value"><strong>${value}</strong><em>/ ${max}</em></div><div class="vital-controls">${button('−','adjust',`data-path="${path}" data-delta="-1" aria-label="Reduce ${label}"`)}${button('+','adjust',`data-path="${path}" data-delta="1" aria-label="Increase ${label}"`)}</div><div class="meter"><span style="width:${Math.min(100,100*value/Math.max(1,max))}%"></span></div></div>`;}
function dice(pool){return `<span class="dice" aria-label="${pool.proficiency} Proficiency, ${pool.ability} Ability">${'<i class="die proficiency"></i>'.repeat(pool.proficiency)}${'<i class="die"></i>'.repeat(pool.ability)}<span class="dice-count">${pool.proficiency}P ${pool.ability}A</span></span>`;}
function bodyArt(suit=false){return `<svg class="${suit?'suit-art':''}" viewBox="0 0 240 280" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path opacity=".3" stroke-dasharray="4 5" d="M120 5v270M15 65h210M15 150h210M15 240h210"/><circle cx="120" cy="40" r="25"/><path d="M101 22h38l6 30-10 16h-30L95 52zM104 40h32v12h-32zM108 58h24M98 75 70 82 60 130 75 145 85 115 87 160h66l2-45 10 30 15-15-10-48-28-7M97 78h46v56H97zM104 88h32v30h-32zM61 132 51 182 67 188l14-43m98-13 10 50-16 6-14-43M88 164l-8 66h27l13-55 13 55h27l-8-66M80 234l-8 27h35v-27m26 0v27h35l-8-27M88 145h64"/><path opacity=".5" d="M30 35h25m-25 0v22m155-22h25v22M30 225v30h25m130 0h25v-30"/>${suit?'<path stroke-width="4" d="M69 81 49 90l-6 30 18 8m110-47 20 9 6 30-18 8M93 78l-8 67m62-67 8 67M83 189h27m20 0h27"/>':''}</svg>`;}
function conditions(){const list=[];if(c.wounds>c.woundThreshold)list.push('Wound threshold exceeded');if(c.strain>effectiveStrain(c))list.push('Strain threshold exceeded');if(c.rads>=9)list.push('Radiation incapacitation');if(c.chems.withdrawal)list.push('Withdrawal: one Setback on all checks');return list;}
function characterView(){const warnings=conditions();return `${title('Personal record','Character',button('Edit sheet','edit-character') )}<div class="character-layout"><section class="identity-card"><div class="portrait">${c.portrait?`<img src="${c.portrait}" alt="${esc(c.name)} portrait">`:bodyArt()}<span class="portrait-label">FIELD IDENTIFICATION</span></div><div class="identity-copy"><span class="eyebrow">${esc(c.species)} / ${esc(c.background)}</span><h2>${esc(c.name)}</h2><p>${esc(c.career||'Career unassigned')}${c.specialization?' · '+esc(c.specialization):''}</p><p class="muted">${esc(c.location||'Location not recorded')}</p>${button(c.portrait?'Change portrait':'Add portrait','portrait','','plain small')}</div><div class="identity-footer"><span>RECORD ${c.id.slice(0,8).toUpperCase()}</span><span>ACTIVE</span></div></section><div class="stats-column"><div class="resource-strip"><div class="resource"><small>AVAILABLE XP</small><strong>${c.xp} <span class="small">/ ${c.totalXp} total</span></strong></div><div class="resource"><small>BOTTLE CAPS</small><strong>${c.caps.toLocaleString()}</strong></div><div class="resource"><small>OBLIGATION</small><strong>${c.obligation}</strong></div></div><div class="vitals">${gauge('Wounds',c.wounds,c.woundThreshold,'wounds',c.wounds>c.woundThreshold)}${gauge('Strain',c.strain,effectiveStrain(c),'strain',c.strain>effectiveStrain(c))}${gauge('Radiation',c.rads,9,'rads',c.rads>=3)}</div><div class="section-label">Characteristics <small>${suitActive(c)?'POWERED SUIT VALUES':'PERSONAL VALUES'}</small></div><div class="attributes">${ATTRIBUTES.map(a=>`<div class="attribute"><span>${a}</span><strong>${attribute(c,a)}</strong><small>${attribute(c,a)!==c.attributes[a]?'BASE '+c.attributes[a]:'&nbsp;'}</small></div>`).join('')}</div><div class="two-col wide-section"><div class="panel"><span class="eyebrow">Personal protection</span><span class="stat-number">${c.soak+(c.chems.active.includes('Med-X')?2:0)}</span> <span class="muted">soak</span><p class="small muted padded-top">Defence ${c.defenceMelee} melee / ${c.defenceRanged} ranged</p></div><div class="panel"><span class="eyebrow">Luck pool</span><div class="inline-actions"><span class="stat-number">${c.luckPlayer}</span><span class="muted">player / ${c.luckGM} GM</span></div><div class="inline-actions padded-top">${button('Use player','luck-player','','small-button')}${button('Use GM','luck-gm','','small-button')}</div></div></div></div></div>${warnings.length?`<div class="status-banner">${icon('warn')}<span>${warnings.join(' · ')}</span></div>`:`<div class="status-banner ok">${icon('person')}<span>${c.rads>=3?`Radiation reduces strain threshold by ${radPenalty(c.rads)}.`:'No incapacitating conditions recorded.'} ${suitActive(c)?`${suitFor(c).name} active; Resilience still uses biological Brawn.`:''}</span></div>`}<section class="panel wide-section"><div class="panel-header"><h2>Skills & training</h2>${button('Edit skills','edit-skills','','small-button')}</div><p class="small muted">Green: Ability · Amber: Proficiency. These are positive dice pools; add difficulty, Boost and Setback at the table.</p><div class="skill-grid">${SKILLS.map(([name,a])=>`<div class="skill-row"><span class="skill-label">${name}<small>${a} · Rank ${c.skills[name].rank}${c.skills[name].career?' · Career':''}</small></span>${dice(skillPool(c,name))}</div>`).join('')}</div></section><div class="two-col wide-section"><section class="panel"><div class="panel-header"><h2>Talents & abilities</h2>${button('Add talent','add-talent','','small-button')}</div>${c.talents.length?c.talents.map(t=>`<button class="record-row" data-action="edit-talent" data-id="${t.id}"><span><strong>${esc(t.name)}</strong><small>Rank ${t.rank} · ${t.cost} XP recorded</small></span></button>`).join(''):'<p class="muted">Record purchased talents and species abilities here.</p>'}${c.power.trained?'<p class="tag padded-top">Power Armour Training acquired</p>':''}</section><section class="panel"><h2>Obligation & motivation</h2><p class="text-block">${esc(c.obligationNotes||'No obligation details recorded.')}</p><p class="text-block muted">${esc(c.motivation||'No motivation recorded.')}</p></section></div>`;}
function melee(w){return ['Melee','Brawl'].includes(w.skill);}
function equipmentView(){return `${title('Combat equipment','Loadout',button('Add weapon','add-weapon'))}<p class="rule-note">Weapon cards use agreed EotE stats. The price catalogue supplies prices, not converted combat profiles. Ammo is spent on every attack, including misses.</p>${c.weapons.length?c.weapons.map(w=>`<section class="panel wide-section weapon-card"><div><span class="eyebrow">${esc(w.scale)} SCALE · ${esc(w.skill)}</span><h2>${esc(w.name)}</h2><div class="weapon-data"><span>Damage<b>${w.damage}${w.scale==='personal'&&c.chems.active.includes('Psycho')?' + 2 Psycho':''}</b></span><span>Critical<b>${w.crit}</b></span><span>Range<b>${esc(w.range)}</b></span></div><p class="small muted">${esc(w.qualities||'No qualities recorded')}</p>${melee(w)?'<p class="small muted">Melee weapon · no ammunition. Damage records the final base, including Brawn.</p>':`<div class="ammo-line"><strong>${w.loaded} / ${w.capacity}</strong><span>${esc(w.ammo)} · ${c.ammo[w.ammo]||0} reserve</span></div>`}<div class="inline-actions">${melee(w)?'':button(`Fire (${w.cost})`,'fire',`data-id="${w.id}"`,'primary')}${w.auto?button('Auto-fire (10)','auto-fire',`data-id="${w.id}"`):''}${melee(w)?'':button(w.reload==='individual'?'Load 2':'Reload','reload',`data-id="${w.id}"`)}${button('Edit','edit-weapon',`data-id="${w.id}"`,'plain')}</div></div><span class="tag">${melee(w)?'MELEE':w.reload==='individual'?'2 / MANEUVER':'1 MANEUVER RELOAD'}</span></section>`).join(''):`<div class="empty"><h3>No weapons recorded</h3><p>Add a weapon with your agreed damage, qualities and magazine capacity.</p>${button('Add your first weapon','add-weapon','','primary')}</div>`}<section class="panel wide-section"><div class="panel-header"><h2>Ammunition reserves</h2>${button('Adjust reserves','edit-ammo','','small-button')}</div>${Object.keys(c.ammo).length?Object.entries(c.ammo).map(([name,n])=>`<div class="record-row"><span>${esc(name)}</span><strong class="record-side">${n}</strong></div>`).join(''):'<p class="muted">Reserves are shared by weapons using exactly the same ammo type. Buy ammunition in the catalogue or record scavenged rounds.</p>'}</section><div class="two-col wide-section"><div class="panel"><h3>Reloading</h3><p class="small muted">A magazine, belt or pack takes one maneuver. Individually loaded weapons take two rounds per maneuver. Refilling a loose magazine takes an action. Keep Prepare, Slow-Firing and Limited Ammo.</p></div><div class="panel"><h3>Power and heavy weapons</h3><p class="small muted">A suit does not change weapon scale. A Gatling laser weapon core supplies 500 charges; Auto-fire costs 10. Record it separately from the suit’s adventure core. Mounted weapons retain their own stats and scale.</p></div></div>`;}
function powerView(){const s=suitFor(c),active=suitActive(c);return `${title('Wearable vehicle','Power armour',button('Configure suit','edit-power'))}<div class="suit-layout"><section class="panel"><span class="eyebrow">${c.power.owned?'ASSIGNED CHASSIS':'REFERENCE CHASSIS'}</span>${bodyArt(true)}<h2>${s.name}</h2><span class="tag ${active?'':'amber'}">${active?'POWERED & EQUIPPED':!c.power.owned?'NOT OWNED':c.power.hull>s.hull?'DISABLED':c.power.system>s.system?'SHUT DOWN':c.power.equipped?'EQUIPPED / UNPOWERED':'NOT EQUIPPED'}</span><p class="small muted padded-top">Silhouette 2 · Defence 0<br>Handling 0 · Crew 1</p></section><div><div class="panel"><div class="panel-header"><h2>Chassis status</h2><span class="tag">VEHICLE SCALE</span></div><div class="suit-stats"><div><small>Armour</small><strong>${s.armour}</strong></div><div><small>Brawn</small><strong>${s.brawn}</strong></div><div><small>Agility</small><strong>${s.agility}</strong></div><div><small>Trained Agility</small><strong>${c.power.trained?Math.max(s.agility,c.attributes.Agility):'—'}</strong></div></div><div class="two-col">${gauge('Hull trauma',c.power.hull,s.hull,'power.hull',c.power.hull>s.hull)}${gauge('System strain',c.power.system,s.system,'power.system',c.power.system>s.system)}</div><p class="small muted padded-top">Core: ${esc(c.power.core)}. One full core per adventure; record partial or spent cores explicitly.</p><div class="inline-actions">${button(c.power.equipped?'Exit suit':'Enter suit','toggle-suit',c.power.owned?'':'disabled')}${button(c.power.powered?'Switch power off':'Switch power on','toggle-power',c.power.owned?'':'disabled')}${button(c.power.trained?'Training acquired':'Buy training · 20 XP','training',c.power.trained?'disabled':'')}</div></div><div class="panel wide-section"><h2>Incoming damage</h2><p class="small muted">Apply each hit separately. Armour blocks groups of 10; any positive remainder rounds up to whole hull trauma.</p><form id="damage-form"><div class="form-grid three">${field('Total damage','damage',13,'number','min="0" max="100000" required')}${field('Pierce','pierce',0,'number','min="0" max="1000" required')}${field('Breach','breach',0,'number','min="0" max="1000" required')}${select('Attack scale','scale',[['personal','Personal'],['vehicle','Vehicle']],'personal')}</div><div class="calc-output"><span>Hull trauma this hit</span><strong id="damage-output">${hullDamage(13,s.armour)}</strong></div><button type="submit" class="primary" ${c.power.owned&&c.power.equipped?'':'disabled'}>Apply to suit</button></form></div></div></div><div class="two-col wide-section"><section class="panel"><h2>Physical characteristics</h2><p class="small muted">Powered suit Brawn and Agility replace your own for physical tasks. Training lets you use the higher Agility. Biological Resilience uses your Brawn. Suit stats never increase personal wound or strain thresholds.</p><p class="small muted">Entry or exit: an action and a maneuver. Walking uses personal maneuvers. An unpowered suit cannot walk; its plates still protect.</p></section><section class="panel"><h2>Armour & criticals</h2><p class="small muted">Pierce below 10 does nothing to vehicle Armour. Each full 10 Pierce ignores 1 Armour; Breach ignores Armour directly. Personal damage = ceil((damage − 10 × remaining Armour) / 10), minimum zero.</p><p class="text-block small">${esc(c.power.criticals||'No vehicle criticals recorded.')}</p><p class="small muted">Use the vehicle critical table after at least 1 hull trauma. Exceeding a threshold disables the suit; hull does not pass through as wounds.</p></section></div>`;}
function healthView(){return `${title('Medical record','Health & chems',button('Edit conditions','edit-health'))}<div class="three-col">${gauge('Wounds',c.wounds,c.woundThreshold,'wounds',c.wounds>c.woundThreshold)}${gauge('Strain',c.strain,effectiveStrain(c),'strain',c.strain>effectiveStrain(c))}${gauge('Radiation',c.rads,9,'rads',c.rads>=3)}</div><div class="two-col wide-section"><section class="panel"><h2>Radiation</h2><p class="small muted">0–2 Rads: no penalty. 3–5: strain threshold −2. 6–8: −4 instead. 9+: incapacitated until below 9. Rest and stimpaks do not clear Rads.</p><p class="small">Resilience uses biological Brawn ${attribute(c,'Brawn',true)}. Rad-X and sealed, functioning armour each grant two Boost dice; they stack.</p><p class="small muted">Failed exposure checks: Easy 1 Rad, Average 2, Hard 3. One check per contaminated meal/drink, persistent hour, or acute encounter.</p><div class="inline-actions">${[1,2,3].map(n=>button(`+${n} Rad${n>1?'s':''}`,'exposure',`data-n="${n}"`)).join('')}</div></section><section class="panel"><h2>Active effects</h2><p>${c.chems.active.length?c.chems.active.map(n=>`<span class="tag">${esc(n)}</span>`).join(' '):'<span class="muted">No active chems</span>'}</p><p class="small muted">${c.chems.doses} addictive doses this encounter · ${c.chems.stimpaks} stimpaks today</p><p class="small">${c.chems.pendingRadAway} RadAway dose(s) awaiting one in-world hour.</p><div class="inline-actions">${button('End encounter','end-encounter','','small-button')}${button('One hour passes','hour','','small-button')}${button('New day','new-day','','small-button')}</div><p class="small muted padded-top">Story time advances only when you use these controls. Resolve addiction with biological Resilience after effects end; two or more doses upgrade the Average check once.</p></section></div><div class="section-label">Carried medication <small>One maneuver to take a ready dose</small></div><div class="chem-grid">${CHEMS.map(ch=>{const count=c.inventory.filter(i=>i.name.toLowerCase()===ch.name.toLowerCase()&&i.location==='On you').reduce((n,i)=>n+i.quantity,0);return `<section class="panel chem-card"><div class="panel-header"><h3>${ch.name}</h3><span class="tag ${ch.addictive?'amber':''}">${ch.addictive?'ADDICTIVE':'MEDICAL'}</span></div><p>${ch.effect}</p><div class="inline-actions"><span class="small muted">${count} carried</span>${button('Use dose','use-chem',`data-name="${ch.name}" ${count?'':'disabled'}`)}</div></section>`;}).join('')}</div><div class="two-col wide-section"><section class="panel"><h2>Critical injuries</h2><p class="text-block muted">${esc(c.criticalInjuries||'No critical injuries recorded.')}</p></section><section class="panel"><h2>Dependence</h2><p class="text-block">${esc(c.chems.dependence||'None recorded')}</p><p class="small muted">${c.chems.withdrawal?'Withdrawal active: one Setback on all checks.':'Withdrawal not active.'} After 24 hours without the dependent chem, mark withdrawal. A dose suppresses it for 24 hours; Addictol or seven days without addictive chems ends dependence. Update timed dependence manually.</p></section></div>`;}

const categories=[['Weapons','weapon'],['Armor','armor'],['Apparel','person'],['Chems','medical'],['Food','food'],['Drinks','food'],['Junk','tool'],['Components','tool'],['Power armor','vehicle'],['Other','pack']];
function inventoryView(){const locations=[...new Set(c.inventory.filter(i=>i.location!=='On you').map(i=>i.location))];const loc=inventoryMode==='On you'?'On you':inventoryLocation;const items=c.inventory.filter(i=>i.location===loc&&(!inventoryCategory||i.category===inventoryCategory));return `${title('Equipment & supplies','Inventory',`<span class="tag amber">${c.caps.toLocaleString()} CAPS</span>`)}<div class="segmented">${['On you','Storage','Catalogue'].map(m=>button(m,'inventory-mode',`data-mode="${m}" aria-pressed="${inventoryMode===m}"`)).join('')}</div>${inventoryMode==='Catalogue'?catalogueView():`<div class="inline-actions">${button('Add item','add-item','','primary')}${button('Adjust caps','edit-caps')}${inventoryCategory?button('All categories','all-categories'):''}</div>${inventoryMode==='Storage'?`<div class="segmented padded-top">${locations.map(l=>button(esc(l),'location',`data-location="${esc(l)}" aria-pressed="${inventoryLocation===l}"`)).join('')||'<p class="muted">Add an item and give it a storage location.</p>'}</div>`:''}${!inventoryCategory?`<div class="inventory-grid wide-section">${categories.map(([cat,i])=>{const n=c.inventory.filter(x=>x.location===loc&&x.category===cat).reduce((n,x)=>n+x.quantity,0);return `<button class="inventory-tile" data-action="category" data-category="${cat}">${icon(i)}<strong>${cat}</strong><small>${n} item${n===1?'':'s'}</small></button>`;}).join('')}</div>`:`<section class="panel wide-section"><h2>${esc(inventoryCategory)} <span class="small muted">/ ${esc(loc||'Select a location')}</span></h2>${items.length?items.map(i=>`<button class="record-row" data-action="item" data-id="${i.id}"><span><strong>${esc(i.name)}</strong><small>${esc(i.notes||i.location)}</small></span><span class="record-side">×${i.quantity}</span></button>`).join(''):'<p class="muted">Nothing recorded here.</p>'}</section>`}<p class="small muted padded-top">Ammunition is tracked in Loadout. Catalogue purchases go into carried inventory or shared ammo reserves.</p>`}`;}
function catalogueView(){return `<p class="small muted">668 sourced Fallout 4 items. Base value is a game reference; shop is the campaign baseline (3× base). Stock and access remain GM decisions.</p><div class="toolbar"><label>Search catalogue<input id="catalogue-search" type="search" placeholder="10mm, stimpak, T-45…" value="${esc(catalogueSearch)}"></label><label>Category<select id="catalogue-category">${['All',...new Set(catalogue.map(i=>i.category))].map(x=>`<option ${catalogueCategory===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><button data-action="economy-help">Price guide</button></div><div id="catalogue-results"></div>`;}
function catalogueResults(){if(!$('#catalogue-results'))return;const found=catalogue.filter(i=>(catalogueCategory==='All'||i.category===catalogueCategory)&&i.name.toLowerCase().includes(catalogueSearch.toLowerCase()));const pages=Math.max(1,Math.ceil(found.length/20));cataloguePage=Math.min(cataloguePage,pages-1);const slice=found.slice(cataloguePage*20,cataloguePage*20+20);$('#catalogue-results').innerHTML=found.length?`<div class="table-wrap catalogue-table"><table><thead><tr><th>Item</th><th>Category</th><th>Base</th><th>Shop</th><th>Record</th></tr></thead><tbody>${slice.map(i=>`<tr><td>${esc(i.name)}</td><td class="muted">${esc(i.category)}</td><td class="price">${i.value.toLocaleString()}</td><td class="price">${i.shop==null?'—':i.shop.toLocaleString()}</td><td>${button('View','catalogue-item',`data-id="${i.id}"`,'small-button')}</td></tr>`).join('')}</tbody></table></div><div class="catalogue-mobile">${slice.map(i=>`<button class="record-row" data-action="catalogue-item" data-id="${i.id}"><span><strong>${esc(i.name)}</strong><small>${esc(i.category)} · Base ${i.value}</small></span><span class="record-side">${i.shop==null?'—':i.shop.toLocaleString()}<small>CAPS / SHOP</small></span></button>`).join('')}</div><div class="pagination">${button('Previous','catalogue-page',`data-delta="-1" ${cataloguePage===0?'disabled':''}`)}<span>${found.length} items · ${cataloguePage+1} / ${pages}</span>${button('Next','catalogue-page',`data-delta="1" ${cataloguePage===pages-1?'disabled':''}`)}</div>`:'<div class="empty">No matching items.</div>';}
function journalView(){return `${title('Campaign log','Journal',button('New entry','add-journal'))}<div class="panel"><div class="panel-header"><div><span class="eyebrow">Story clock</span><h2>${esc(c.storyDate||'Date not set')}</h2></div>${button('Edit','edit-clock','','small-button')}</div><p class="muted">${esc(c.location||'Location not set')}</p><p class="small muted">This is in-world time. Your record does not advance the story automatically.</p></div>${c.journal.length?c.journal.map(j=>`<article class="journal-entry"><div class="panel-header"><div><span class="eyebrow">${esc(j.date||'UNDATED')}</span><h2>${esc(j.title)}</h2></div>${button('Edit','edit-journal',`data-id="${j.id}"`,'small-button')}</div><p class="text-block">${esc(j.body)}</p></article>`).join(''):'<div class="empty wide-section"><h3>The next story is yours</h3><p>Keep session notes, discoveries and promises in your field journal.</p></div>'}<section class="panel wide-section"><div class="panel-header"><h2>Reference notes</h2>${button('Edit notes','edit-notes','','small-button')}</div><p class="text-block muted">${esc(c.notes||'No notes yet.')}</p></section>`;}
function render(){if(!NAV.some(n=>n[0]===tab))tab='character';$('#navigation').innerHTML=NAV.map(([id,i,n])=>`<a href="#${id}" ${id===tab?'aria-current="page"':''}>${icon(i)}<span>${n}</span></a>`).join('');$('#main').innerHTML=({character:characterView,equipment:equipmentView,power:powerView,health:healthView,inventory:inventoryView,journal:journalView})[tab]();document.title=`${NAV.find(x=>x[0]===tab)[2]} · Fallout Stories`;if(tab==='inventory'&&inventoryMode==='Catalogue'){catalogueResults();$('#catalogue-search').addEventListener('input',e=>{catalogueSearch=e.target.value;cataloguePage=0;catalogueResults();});$('#catalogue-category').addEventListener('change',e=>{catalogueCategory=e.target.value;cataloguePage=0;catalogueResults();});}if(tab==='power'){$('#damage-form').addEventListener('input',updateDamage);$('#damage-form').addEventListener('submit',e=>{e.preventDefault();const n=damageResult();c.power.hull+=n;commit(`${n} hull trauma applied.`);});}}
function damageResult(){const d=new FormData($('#damage-form'));return hullDamage(num(d,'damage'),suitFor(c).armour,num(d,'pierce'),num(d,'breach'),d.get('scale'));}
function updateDamage(){$('#damage-output').textContent=damageResult();}
function editCharacter(){form('Edit character',field('Name','name',c.name,'text','required maxlength="200"')+field('Species','species',c.species)+field('Background','background',c.background)+field('Career','career',c.career)+field('Specialization','specialization',c.specialization)+field('Available XP','xp',c.xp,'number','min="0" required')+field('Total XP earned','totalXp',c.totalXp,'number','min="0" required')+field('Caps','caps',c.caps,'number','min="0" required')+ATTRIBUTES.map(a=>field(a,a,c.attributes[a],'number','min="1" max="6" required')).join('')+field('Wound threshold','woundThreshold',c.woundThreshold,'number','min="1" required')+field('Base strain threshold','strainThreshold',c.strainThreshold,'number','min="1" required')+field('Personal soak (before chems)','soak',c.soak,'number','min="0" required')+field('Melee defence','defenceMelee',c.defenceMelee,'number','min="0" required')+field('Ranged defence','defenceRanged',c.defenceRanged,'number','min="0" required')+field('Obligation value','obligation',c.obligation,'number','min="0" required')+field('Player Luck','luckPlayer',c.luckPlayer,'number','min="0" required')+field('GM Luck','luckGM',c.luckGM,'number','min="0" required')+area('Obligation details','obligationNotes',c.obligationNotes)+area('Motivation','motivation',c.motivation)+'<p class="small muted full">Thresholds, soak and XP are recorded explicitly: apply species, talents and armour bonuses yourself. This is a blank human template, not a completed legal character build.</p>',d=>{for(const k of ['name','species','background','career','specialization','obligationNotes','motivation'])c[k]=d.get(k).trim();for(const k of ['xp','totalXp','caps','woundThreshold','strainThreshold','soak','defenceMelee','defenceRanged','obligation','luckPlayer','luckGM'])c[k]=num(d,k);for(const a of ATTRIBUTES)c.attributes[a]=num(d,a);});}
function editSkills(){form('Skills & training',SKILLS.map(([name,a],i)=>`<div>${field(`${name} · ${a}`,'rank'+i,c.skills[name].rank,'number','min="0" max="5" required')}${check('Career skill','career'+i,c.skills[name].career)}</div>`).join('')+'<p class="small muted full">These fields record your sheet. XP is not deducted when correcting ranks.</p>',d=>{SKILLS.forEach(([name],i)=>c.skills[name]={rank:num(d,'rank'+i),career:d.has('career'+i)});});}
function editPower(){form('Configure power armour',select('Suit profile','profile',SUITS.map(s=>[s.id,s.name]),c.power.profile)+field('Core record','core',c.power.core)+check('Suit owned / assigned','owned',c.power.owned)+check('Equipped','equipped',c.power.equipped)+check('Powered (requires a usable core)','powered',c.power.powered)+check('Training already acquired','trained',c.power.trained)+field('Hull trauma','hull',c.power.hull,'number','min="0" required')+field('System strain','system',c.power.system,'number','min="0" required')+area('Vehicle criticals & damage','criticals',c.power.criticals)+'<p class="small muted full">Changing the profile records a different suit; it does not buy one. Training checked here records a prior purchase. The Buy training button deducts 20 XP.</p>',d=>{for(const k of ['profile','core','criticals'])c.power[k]=d.get(k);for(const k of ['owned','equipped','powered','trained'])c.power[k]=d.has(k);for(const k of ['hull','system'])c.power[k]=num(d,k);if(!c.power.owned){c.power.equipped=false;c.power.powered=false;}});}
function editHealth(){form('Conditions & medical record',field('Wounds','wounds',c.wounds,'number','min="0" required')+field('Strain','strain',c.strain,'number','min="0" required')+field('Rads','rads',c.rads,'number','min="0" required')+field('Stimpaks today','stimpaks',c.chems.stimpaks,'number','min="0" required')+field('Pending RadAway doses','pendingRadAway',c.chems.pendingRadAway,'number','min="0" required')+field('Addictive doses this encounter','doses',c.chems.doses,'number','min="0" required')+area('Dependence (chem names)','dependence',c.chems.dependence)+check('Withdrawal active','withdrawal',c.chems.withdrawal)+area('Critical injuries','criticalInjuries',c.criticalInjuries)+CHEMS.filter(x=>!['Stimpak','RadAway','Addictol'].includes(x.name)).map(x=>check(x.name+' active',x.name,c.chems.active.includes(x.name))).join(''),d=>{for(const k of ['wounds','strain','rads'])c[k]=num(d,k);for(const k of ['stimpaks','pendingRadAway','doses'])c.chems[k]=num(d,k);c.chems.dependence=d.get('dependence');c.chems.withdrawal=d.has('withdrawal');c.criticalInjuries=d.get('criticalInjuries');c.chems.active=CHEMS.filter(x=>d.has(x.name)).map(x=>x.name);});}
function editWeapon(id){const existing=c.weapons.find(w=>w.id===id);const w=existing||{id:uid(),name:'',skill:'Ranged Light',scale:'personal',damage:5,crit:3,range:'Medium',qualities:'',ammo:'10mm Round',capacity:12,loaded:0,cost:1,auto:false,reload:'magazine'};form(existing?'Edit weapon':'Add weapon',field('Name','name',w.name,'text','required maxlength="200"')+select('Attack skill','skill',['Ranged Light','Ranged Heavy','Gunnery','Melee','Brawl'],w.skill)+select('Scale','scale',[['personal','Personal'],['vehicle','Vehicle']],w.scale)+field('Damage (final base)','damage',w.damage,'number','min="0" required')+field('Critical rating','crit',w.crit,'number','min="1" max="10" required')+select('Range','range',['Engaged','Short','Medium','Long','Extreme'],w.range)+field('Ammo type (exact reserve name)','ammo',w.ammo,'text','required maxlength="200" list="ammo-types"')+`<datalist id="ammo-types">${catalogue.filter(i=>i.category==='Ammunition').map(i=>`<option value="${esc(i.name)}">`).join('')}<option value="Fusion core charges"></datalist>`+field('Capacity','capacity',w.capacity,'number','min="0" max="10000" required')+field('Loaded rounds / charges','loaded',w.loaded,'number','min="0" max="10000" required')+field('Normal attack ammo cost','cost',w.cost,'number','min="0" max="10000" required')+select('Reload','reload',[['magazine','Magazine / belt / pack'],['individual','Individual rounds (2 / maneuver)']],w.reload)+check('Auto-fire capable','auto',w.auto)+area('Qualities & conversion notes','qualities',w.qualities)+'<p class="small muted full">Editing loaded ammo is a manual correction, not a reload. Melee/Brawl cards ignore ammo fields; their final base damage should already include current Brawn. A price-catalogue purchase does not assign combat stats.</p>'+(existing?`<div class="full">${button('Remove weapon card','remove-weapon',`data-id="${w.id}"`,'danger')}</div>`:''),d=>{const next={...w};for(const k of ['name','skill','scale','range','ammo','reload','qualities'])next[k]=d.get(k).trim();for(const k of ['damage','crit','capacity','loaded','cost'])next[k]=num(d,k);next.auto=d.has('auto');if(melee(next)){next.ammo='None';next.capacity=0;next.loaded=0;next.cost=0;next.auto=false;}else if(next.capacity<1||next.cost<1)throw Error('Ranged weapons require positive capacity and ammo cost.');if(next.loaded>next.capacity)throw Error('Loaded ammo exceeds capacity.');if(['__proto__','constructor','prototype'].includes(next.ammo))throw Error('Invalid ammo name.');if(existing)Object.assign(existing,next);else c.weapons.push(next);});}
function editAmmo(){form('Ammunition reserve',select('Ammo type','type',[...new Set([...catalogue.filter(i=>i.category==='Ammunition').map(i=>i.name),...Object.keys(c.ammo),'Fusion core charges'])],'10mm Round')+field('New reserve total','amount',0,'number','min="0" required')+field('Custom type (optional)','custom','')+'<p class="full small muted">Set the total in reserve, excluding loaded ammunition. Reload moves rounds into the weapon without creating new ammo. Suit power cores remain a separate record.</p>',d=>{const key=d.get('custom').trim()||d.get('type');if(['__proto__','constructor','prototype'].includes(key))throw Error('Invalid ammo name.');c.ammo[key]=num(d,'amount');});const update=()=>{$('#edit-form [name=amount]').value=c.ammo[$('#edit-form [name=type]').value]||0;};$('#edit-form [name=type]').addEventListener('change',update);update();}
function editItem(id){const existing=c.inventory.find(i=>i.id===id),i=existing||{id:uid(),name:'',category:'Other',quantity:1,location:inventoryMode==='Storage'?(inventoryLocation||'Settlement stash'):'On you',value:0,notes:''};form(existing?'Edit inventory item':'Add inventory item',field('Item name','name',i.name,'text','required maxlength="200"')+select('Category','category',categories.map(x=>x[0]),i.category)+field('Quantity','quantity',i.quantity,'number','min="1" required')+field('Location (On you = carried)','location',i.location,'text','required maxlength="200"')+field('Base value per item','value',i.value,'number','min="0" required')+area('Notes','notes',i.notes)+'<p class="small muted full">This records possessions without spending caps. Use the catalogue to buy items at campaign prices.</p>',d=>{const next={...i,name:d.get('name').trim(),category:d.get('category'),quantity:num(d,'quantity'),location:d.get('location').trim(),value:num(d,'value'),notes:d.get('notes')};if(existing)Object.assign(existing,next);else c.inventory.push(next);});}
function itemDetail(id){const i=c.inventory.find(x=>x.id===id);modal('Inventory item',`<h2>${esc(i.name)}</h2><p class="muted">${esc(i.category)} · ${esc(i.location)}</p><p>Quantity: <strong>${i.quantity}</strong> · Base value: <strong>${i.value} caps</strong></p><p class="text-block">${esc(i.notes)}</p><p class="small muted">Sell value: half the lot’s base value, rounded down. Selling assumes a buyer is available.</p><div class="inline-actions">${button('Edit / move','edit-item',`data-id="${id}"`)}${button('Sell one','sell-item',`data-id="${id}"`)}${button('Remove one','remove-item',`data-id="${id}"`,'danger')}</div>`);}
function catalogueDetail(id){const i=catalogue.find(x=>x.id===id);modal('Catalogue record',`<span class="eyebrow">${i.id} · ${esc(i.category)}</span><h2>${esc(i.name)}</h2><div class="resource-strip"><div><small>GAME BASE VALUE</small><strong>${i.value.toLocaleString()}</strong></div><div><small>CAMPAIGN SHOP</small><strong>${i.shop==null?'GM price':i.shop.toLocaleString()}</strong></div></div><p class="small muted">${esc(i.game)} · ${i.code==='C'?'Corroborated across two references':i.code==='B'?'Selected base profile':'One reference checked'}. Values are reference item values, not a promise of vendor availability.</p><div class="reference-links small"><a href="${esc(i.item_url||i.source)}" target="_blank" rel="noopener">Item reference</a><a href="${esc(i.source)}" target="_blank" rel="noopener">${esc(i.source_id)} · Source table</a>${i.cross_source?`<a href="${esc(i.cross_source)}" target="_blank" rel="noopener">${esc(i.cross_id)} · Cross-reference</a>`:''}</div>${i.shop==null?'<p class="rule-note padded-top">No routine shop price. Agree a price with the GM and record it manually.</p>':`<form id="buy-form" class="padded-top"><div class="form-grid">${field('Quantity','quantity',1,'number','min="1" max="10000" required')}${select('Availability / scarcity','scarcity',[['1','Normal ×1'],['1.5','Scarce ×1.5'],['2','Rare ×2']],'1')}${select('Negotiation discount','discount',[['0','None'],['0.05','5%'],['0.1','10%'],['0.15','15%'],['0.2','20%']],'0')}</div><div class="calc-output"><span>Total caps</span><strong id="buy-total">${i.shop}</strong></div><p class="form-error" id="buy-error" role="alert"></p><button type="submit" class="primary">Buy & add to inventory</button><p class="small muted padded-top">Confirm stock with the GM. Buying weapons adds the item; create a loadout card with agreed combat stats separately.</p></form>`}`);if(i.shop!=null){const price=()=>{const d=new FormData($('#buy-form'));return quote(i,num(d,'quantity'),num(d,'scarcity'),num(d,'discount'));};$('#buy-form').addEventListener('input',()=>{$('#buy-total').textContent=price().toLocaleString();});$('#buy-form').addEventListener('submit',e=>{e.preventDefault();try{const d=new FormData(e.target);const cost=buy(c,i,num(d,'quantity'),num(d,'scarcity'),num(d,'discount'));$('#detail').close();commit(`Purchased for ${cost.toLocaleString()} caps.`);}catch(err){$('#buy-error').textContent=err.message;}});}}
function editJournal(id){const existing=c.journal.find(j=>j.id===id),j=existing||{id:uid(),title:'',date:c.storyDate,body:''};form(existing?'Edit journal entry':'New journal entry',field('Title','title',j.title,'text','required maxlength="200"')+field('In-world date / session','date',j.date,'text','maxlength="200"')+area('Entry','body',j.body,'required')+(existing?`<div class="full">${button('Delete entry','remove-journal',`data-id="${id}"`,'danger')}</div>`:''),d=>{const next={...j,title:d.get('title'),date:d.get('date'),body:d.get('body')};if(existing)Object.assign(existing,next);else c.journal.unshift(next);});}
function editTalent(id){const existing=c.talents.find(t=>t.id===id),t=existing||{id:uid(),name:'',rank:1,cost:0,notes:''};form(existing?'Edit talent':'Record talent',field('Name','name',t.name,'text','required maxlength="200"')+field('Rank','rank',t.rank,'number','min="1" max="100" required')+field('XP cost recorded','cost',t.cost,'number','min="0" required')+area('Effect & source','notes',t.notes)+'<p class="small muted full">This records an acquired talent. Adjust available XP in Edit sheet; no XP is deducted here.</p>'+(existing?`<div class="full">${button('Remove talent','remove-talent',`data-id="${id}"`,'danger')}</div>`:''),d=>{const next={...t,name:d.get('name'),rank:num(d,'rank'),cost:num(d,'cost'),notes:d.get('notes')};if(existing)Object.assign(existing,next);else c.talents.push(next);});}
function records(){modal('Character records',`<h2>Your field records</h2><p class="muted small">Stored in this browser on this device. Export backups before clearing browser data or switching devices. No cloud sync.</p>${saveProblem?'<p class="form-error">An existing browser save could not be loaded. It has not been overwritten. Export recovery data before enabling saving.</p>'+button('Download recovery data','recover')+button('Enable saving','enable-save'):''}${characters.map(x=>`<button class="record-row" data-action="switch-record" data-id="${x.id}"><span><strong>${esc(x.name)}</strong><small>${esc(x.species)} · ${esc(x.career||'Unassigned career')}</small></span><span class="tag">${x.id===c.id?'CURRENT':'OPEN'}</span></button>`).join('')}<div class="inline-actions padded-top">${button('New character','new-character','','primary')}${button('Export current','export')}${button('Import record','import')}${button('Delete current','delete-character','','danger')}</div>`);}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRecord(){download('fallout-'+c.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.json',JSON.stringify({version:1,character:c},null,2));notify('Character record exported.');}
function confirmAction(titleText,message,label,action){modal(titleText,`<h2>${esc(titleText)}</h2><p>${esc(message)}</p><div class="form-actions"><button data-action="close">Cancel</button><button class="primary" id="confirm-action">${esc(label)}</button></div>`);$('#confirm-action').onclick=()=>{try{action();$('#detail').close();commit();}catch(err){notify(err.message);}};}
function help(){modal('About & campaign rules',`<h2>Your wasteland field companion</h2><p>This app follows the Fallout / EotE conversion agreed for this campaign. It keeps the EotE characteristics and skill pools, with no Force powers.</p><div class="reference-links"><a href="./references/conversion.pdf" target="_blank">Full Fallout EotE conversion</a><a href="./references/economy.pdf" target="_blank">Campaign economy & 668-item roster</a></div><h3 class="padded-top">Using the sheet</h3><p class="small muted">Create a character under Records, edit its attributes and thresholds, then add skills and gear. New records are blank human templates; spend starting XP and assign career skills using your rulebook. Use your phone’s browser menu to add this app to the home screen.</p><h3>Saving & privacy</h3><p class="small muted">Records and portraits stay in this browser’s local storage. They are not uploaded. Export and import JSON to move between devices. Clearing site data removes local records. The app caches its interface and catalogue for offline use after a successful online visit; the character sheet and catalogue are cached once offline preparation completes. Keep exports as backups.</p><h3>Rules at the table</h3><p class="small muted">This is a tracker, not a GM: it does not enforce character creation, award XP, roll dice, advance scenes or automatically resolve criticals. Skill pools show positive dice only. Narrative dice, career trees and the remaining rules use your EotE book.</p><p class="small muted">Layout inspired by your Cyberpunk Stories companion. Fallout and Edge of the Empire belong to their respective owners; this is an unofficial fan campaign tool.</p>`);}
function economyHelp(){modal('Campaign economy',`<h2>Prices with provenance</h2><p>Base values come from the documented Fallout 4 roster. Campaign shop baseline is 3× base; sell lots for half base, rounded down. Zero-value items have no routine shop price.</p><p>Use one opposed Negotiation check. Each net success gives a 5% discount, maximum 20% before talents. Scarcity multiplies prices by 1.5 or 2; availability and faction access remain separate.</p><p>Do not interpret Fallout 4 health, damage or armour numbers as EotE stats. The catalogue is economic evidence, not a combat conversion.</p><p class="small muted">483 corroborated records · 184 single-reference records · 1 selected base profile. All 668 items retain their source links.</p><a href="./references/economy.pdf" target="_blank">Open complete economy document</a>`);}
const actions={
 'close':()=>$('#detail').close(),'edit-character':editCharacter,'edit-skills':editSkills,'edit-power':editPower,'edit-health':editHealth,'edit-ammo':editAmmo,
 'portrait':()=>$('#portrait-file').click(),'add-weapon':()=>editWeapon(),'edit-weapon':b=>editWeapon(b.dataset.id),'add-item':()=>editItem(),'edit-item':b=>editItem(b.dataset.id),'item':b=>itemDetail(b.dataset.id),'add-journal':()=>editJournal(),'edit-journal':b=>editJournal(b.dataset.id),'add-talent':()=>editTalent(),'edit-talent':b=>editTalent(b.dataset.id),
 'edit-clock':()=>form('Story clock',field('In-world date / time','storyDate',c.storyDate)+field('Location','location',c.location),d=>{c.storyDate=d.get('storyDate');c.location=d.get('location');}),
 'edit-notes':()=>form('Reference notes',area('Notes','notes',c.notes),d=>c.notes=d.get('notes')),
 'edit-caps':()=>form('Bottle caps',field('Current caps','caps',c.caps,'number','min="0" required'),d=>c.caps=num(d,'caps')),
 'adjust':b=>{const keys=b.dataset.path.split('.');const obj=keys.length===2?c[keys[0]]:c;const key=keys.at(-1);obj[key]=Math.max(0,obj[key]+Number(b.dataset.delta));commit();},
 'luck-player':()=>{if(!c.luckPlayer)throw Error('No player Luck available. Set the pool in Edit sheet.');c.luckPlayer--;c.luckGM++;commit('Player Luck flipped to GM.');},
 'luck-gm':()=>{if(!c.luckGM)throw Error('No GM Luck available.');c.luckGM--;c.luckPlayer++;commit('GM Luck flipped to player.');},
 'fire':b=>{const n=fireWeapon(c,b.dataset.id);commit(`${n} ammo spent, hit or miss.`);},'auto-fire':b=>{fireWeapon(c,b.dataset.id,true);commit('10 rounds spent for this Auto-fire attack.');},'reload':b=>{const n=reloadWeapon(c,b.dataset.id);commit(`${n} rounds loaded from reserve.`);},
 'remove-weapon':b=>confirmAction('Remove weapon card','Loaded ammunition is not returned to reserves automatically. Correct reserves first if you are unloading this weapon.','Remove card',()=>{c.weapons=c.weapons.filter(w=>w.id!==b.dataset.id);}),
 'toggle-suit':()=>{c.power.equipped=!c.power.equipped;commit(c.power.equipped?'Suit entered: spend an action and a maneuver.':'Suit exited: spend an action and a maneuver.');},'toggle-power':()=>{c.power.powered=!c.power.powered;commit();},
 'training':()=>{if(c.xp<20)throw Error('Power Armour Training requires 20 available XP.');confirmAction('Power Armour Training','Requires an instructor or supervised practice. Spend 20 XP to use your own Agility when it is higher than the suit’s.','Spend 20 XP',()=>{c.xp-=20;c.power.trained=true;});},
 'exposure':b=>{if(c.species.toLowerCase().includes('robot')||c.species.toLowerCase().includes('droid'))throw Error('Robots ignore biological radiation.');c.rads+=Number(b.dataset.n);commit();},
 'use-chem':b=>{const message=useChem(c,b.dataset.name);commit(message);},
 'end-encounter':()=>confirmAction('End encounter','Combat chem effects end. Any addictive doses require an Average biological Resilience check afterward; two or more doses upgrade it once. Record failed dependence in Edit conditions.','End effects',()=>{const doses=c.chems.doses;c.chems.active=c.chems.active.filter(n=>n==='Rad-X');c.chems.doses=0;if(doses)notify(`Resolve ${doses>=2?'upgraded ':''}Average Resilience for addiction now.`);}),
 'hour':()=>confirmAction('One in-world hour passes','Resolve all currently pending RadAway doses and end Rad-X plus any remaining encounter chem effects. Resolve addiction first if needed.','Resolve hour',()=>{c.rads=Math.max(0,c.rads-3*c.chems.pendingRadAway);c.chems.pendingRadAway=0;c.chems.active=[];c.chems.doses=0;}),
 'new-day':()=>confirmAction('New day','Reset the daily stimpak count. Wounds, strain, Rads and dependence stay recorded; resolve recovery and withdrawal at the table.','Reset stimpaks',()=>{c.chems.stimpaks=0;}),
 'inventory-mode':b=>{inventoryMode=b.dataset.mode;inventoryCategory='';render();},'category':b=>{inventoryCategory=b.dataset.category;render();},'all-categories':()=>{inventoryCategory='';render();},'location':b=>{inventoryLocation=b.dataset.location;inventoryCategory='';render();},
 'catalogue-page':b=>{cataloguePage+=Number(b.dataset.delta);catalogueResults();},'catalogue-item':b=>catalogueDetail(b.dataset.id),'economy-help':economyHelp,
 'sell-item':b=>{const amount=sell(c,b.dataset.id);$('#detail').close();commit(`Sold one item for ${amount} caps.`);},'remove-item':b=>{const i=c.inventory.find(i=>i.id===b.dataset.id);i.quantity--;c.inventory=c.inventory.filter(i=>i.quantity>0);$('#detail').close();commit('One item removed.');},
 'remove-journal':b=>confirmAction('Delete journal entry','This removes the entry from this character. Export a backup if you want to keep it.','Delete entry',()=>c.journal=c.journal.filter(j=>j.id!==b.dataset.id)),
 'remove-talent':b=>confirmAction('Remove talent','This does not refund XP.','Remove',()=>c.talents=c.talents.filter(t=>t.id!==b.dataset.id)),
 'switch-record':b=>{c=characters.find(x=>x.id===b.dataset.id);inventoryLocation='';$('#detail').close();commit();},
 'new-character':()=>form('New character',field('Character name','name','','text','required maxlength="200"'),d=>{c=newCharacter(d.get('name').trim());characters.push(c);}),
 'delete-character':()=>confirmAction('Delete current character',`Delete ${c.name} from this device? Export first to keep a backup.`,'Delete record',()=>{characters=characters.filter(x=>x.id!==c.id);if(!characters.length)characters.push(newCharacter());c=characters[0];}),
 'export':exportRecord,'import':()=>$('#import-file').click(),'recover':()=>download('fallout-recovery.json',localStorage.getItem(KEY)||'null'),
 'enable-save':()=>confirmAction('Enable saving','Replace unreadable browser data with the currently displayed records. Download recovery data first if needed.','Enable saving',()=>{saveProblem=false;})
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;try{actions[b.dataset.action]?.(b);}catch(err){notify(err.message);}});
$('#close-dialog').onclick=()=>$('#detail').close();$('#records-button').onclick=records;$('#export-button').onclick=exportRecord;$('#import-button').onclick=()=>$('#import-file').click();$('#help-button').onclick=help;
window.addEventListener('hashchange',()=>{tab=location.hash.slice(1);render();window.scrollTo({top:0});});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5000000)throw Error('Record exceeds the 5 MB import limit.');const parsed=JSON.parse(await file.text());if(parsed.version!==1)throw Error('Unsupported record version.');const imported=validateCharacter(parsed.character);confirmAction('Import character',`Add ${imported.name} as a separate record? Existing characters will be kept.`,'Import record',()=>{imported.id=uid();characters.push(imported);c=imported;});}catch(err){notify('Import rejected: '+err.message);}});
$('#portrait-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8000000)throw Error('Choose a PNG, JPEG or WebP under 8 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);c.portrait=canvas.toDataURL('image/jpeg',.82);bitmap.close();commit('Portrait saved on this device.');}catch(err){notify(err.message);}});
try{const response=await fetch('./catalogue.json');if(!response.ok)throw Error();catalogue=await response.json();}catch{notify('Catalogue unavailable. Your character record is still usable.');}
render();persist();if(saveProblem)records();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function installHelp(){modal('Install on iPhone',`<img class="install-icon" src="./assets/icon-512.png" alt="Fallout Stories power-armour helmet icon"><h2>Take your sheet into the wasteland</h2><ol class="install-steps"><li>Open this site in <strong>Safari</strong> on your iPhone.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>. If it is hidden, use Edit Actions to add it.</li><li>Keep <strong>Open as Web App</strong> enabled if shown, then tap <strong>Add</strong>.</li><li>Open the new Fallout Stories icon and create or import your character there.</li></ol><p id="offline-status" class="offline-status">Checking offline preparation…</p><p class="small muted">Let the installed app finish loading online once before going offline. Records stay on this device; use Export record to keep a backup in Files or move between Safari and the installed app.</p><a href="https://support.apple.com/guide/iphone/open-as-web-app-iphea86e5236/ios" target="_blank" rel="noopener">Apple’s home-screen installation guide</a>`);checkOffline();}
async function checkOffline(){const el=document.getElementById('offline-status');try{if(!('caches' in window)||!('serviceWorker' in navigator))throw Error();const registration=await navigator.serviceWorker.getRegistration('./');const paths=['./index.html','./app.js','./rules.js','./styles.css','./catalogue.json','./references/conversion.pdf','./references/economy.pdf'];const cached=await Promise.all(paths.map(path=>caches.match(new URL(path,location.href).href)));if(el)el.textContent=registration?.active&&cached.every(Boolean)?'Ready offline: character sheet, catalogue and rules.':'Still preparing offline files. Stay online briefly, then reopen this panel to check.';}catch{if(el)el.textContent='Offline installation needs the hosted HTTPS app in Safari.';}}
document.getElementById('install-button').onclick=installHelp;